<?php batasi_akses_role(['admin','petugas']);
$tgl = $_GET['tgl'] ?? date('Y-m-d');
$q=mysqli_query($koneksi,"SELECT p.*, s.namasiswa, s.nis, s.kelas, g.namaguru, g.nip, u.namauser, GROUP_CONCAT(CONCAT(b.namabarang,' x',dp.jumlahkeluar) SEPARATOR ', ') as obat FROM penanganan p LEFT JOIN siswa s ON p.idsiswa=s.idsiswa LEFT JOIN guru g ON p.idguru=g.idguru LEFT JOIN user u ON p.iduser=u.iduser LEFT JOIN detailpenanganan dp ON p.idpenanganan=dp.idpenanganan LEFT JOIN barang b ON dp.idbarang=b.idbarang WHERE DATE(p.tanggalpenanganan)='$tgl' GROUP BY p.idpenanganan ORDER BY p.idpenanganan DESC");
?>
<div class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-6"><h1 class="m-0 text-success font-weight-bold"><i class="fas fa-calendar-day mr-1"></i> Laporan Harian</h1></div><div class="col-sm-6 text-right"><form method="GET" class="form-inline float-right"><input type="hidden" name="halaman" value="laporanharian"><input type="date" name="tgl" value="<?= $tgl ?>" class="form-control form-control-sm mr-2"><button class="btn btn-success btn-sm">Tampilkan</button> <a href="index.php?halaman=cetaklaporanharian&tgl=<?= $tgl ?>" target="_blank" class="btn btn-danger btn-sm ml-1"><i class="fas fa-print"></i> Cetak PDF</a></form></div></div></div></div>
<div class="content"><div class="container-fluid"><div class="card card-success card-outline shadow-sm"><div class="card-body p-0 table-responsive"><table class="table table-bordered mb-0"><thead class="bg-light"><tr><th>No</th><th>Tanggal</th><th>Pasien</th><th>Keluhan</th><th>Tindakan</th><th>Status</th><th>Obat Dipakai</th><th>Petugas</th></tr></thead><tbody><?php $no=1; while($r=mysqli_fetch_assoc($q)): ?><tr><td><?= $no++ ?></td><td><small><?= $r['tanggalpenanganan'] ?></small></td><td><b><?= $r['namasiswa']?:$r['namaguru'] ?></b><br><small class="text-muted"><?= $r['nis']?:$r['nip'] ?> <?= $r['kelas']??'' ?></small></td><td><small><?= htmlspecialchars($r['keluhan']) ?></small></td><td><small><?= htmlspecialchars($r['tindakan']) ?></small></td><td><span class="badge badge-<?= $r['statuspasien']=='sembuh'?'success':($r['statuspasien']=='rujuk'?'danger':'warning') ?>"><?= $r['statuspasien'] ?></span></td><td><small><?= $r['obat']?:'-' ?></small></td><td><small><?= $r['namauser'] ?></small></td></tr><?php endwhile; if(mysqli_num_rows($q)==0) echo '<tr><td colspan="8" class="text-center text-muted p-3">Tidak ada pasien pada tanggal '.$tgl.'</td></tr>'; ?></tbody></table></div></div></div></div>